delete from sms_challenges
where phone_lookup_ref = (
    select phone_lookup_ref
    from accounts
    where account_id = #{accountId}
)

delete from mentor_turns
where account_id_hint = #{accountId}
   or session_id_hint in (
       select session_id
       from account_sessions
       where account_id = #{accountId}
   )

delete from mentor_audit_logs
where account_id_hint = #{accountId}
   or session_id_hint in (
       select session_id
       from account_sessions
       where account_id = #{accountId}
   )

delete from practice_generated_content
where account_id = #{accountId}
  and owner_scope in ('account', 'profile')

mapper.update:
update account_refresh_tokens
set status = 'revoked',
    revoked_at = #{revokedAt},
    updated_at = #{revokedAt}
where account_id = #{accountId}
  and status = 'active'

mapper.delete:
delete from household_shared_context
where household_id in (
    select household_id
    from households
    where owner_account_id = #{accountId}
)

mapper.update:
update caregiver_invite_events e
set actor_account_id = null,
    token = null
where e.actor_account_id = #{accountId}
   or e.token in (
       select invite.token
       from caregiver_invites invite
       where invite.inviter_account_id = #{accountId}
          or invite.accepted_by_account_id = #{accountId}
   )

update caregiver_invites
set accepted_by_account_id = null
where accepted_by_account_id = #{accountId}

update household_members
set invited_by_account_id = null
where invited_by_account_id = #{accountId}

